INSERT INTO `comments` (`id`, `user_id`, `post_id`, `content`, `created_at`, `updated_at`) VALUES
(1, 6, 1, 'Iste esse ducimus voluptate voluptates tempore. Veritatis praesentium ipsam unde doloribus et fugiat. Velit voluptas doloremque natus architecto quasi.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(2, 6, 1, 'Et est ipsum doloremque odio. Cum deserunt qui voluptatem voluptas non laboriosam minus.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(3, 3, 1, 'Nesciunt illo nobis autem. Eligendi atque fugiat aut odio libero.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(4, 4, 2, 'Consequatur dolorem illo architecto et nobis. Ipsum ipsam molestiae eveniet quibusdam quia sed. Error aut eaque vitae delectus ea rem.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(5, 3, 2, 'Minus autem nobis et facilis. Aut nobis ipsum voluptatum et.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(6, 6, 2, 'Enim corporis qui dolores cupiditate nisi. Laborum architecto sapiente rerum repudiandae minima laborum velit. At tempora est dolore quisquam maiores vitae.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(7, 5, 3, 'Voluptatem nam velit sed totam similique deleniti. Voluptatibus quia aspernatur ad perferendis ut.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(8, 5, 3, 'Minus distinctio temporibus maiores provident. Sed dolores saepe odio illo reprehenderit porro maiores est. Harum nobis soluta qui doloremque iste et.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(9, 3, 3, 'Optio sed omnis sint quasi autem distinctio quam eum. Quis optio ipsa enim voluptates eum quis numquam enim.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(10, 2, 4, 'Aut illo esse doloribus quidem. Laboriosam officia vel tenetur voluptas illo consequatur quis.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(11, 6, 4, 'Quaerat rem beatae animi aperiam. Nihil aut vero consequatur a.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(12, 4, 4, 'Ullam similique ut delectus tempore omnis suscipit tempore. Et a non quo non temporibus et molestiae. Commodi quam labore eos voluptatum velit.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(13, 4, 5, 'Occaecati illo incidunt maxime omnis ut culpa. Quia eius harum recusandae consequatur aut.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(14, 3, 5, 'Voluptas rerum sint neque velit. Quis asperiores consequatur quia eum provident.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(15, 3, 5, 'Enim voluptatem consequatur quibusdam rem. Dolore odit alias non harum ullam veniam debitis.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(16, 3, 6, 'Natus et temporibus ut et nemo et repudiandae corrupti. Soluta voluptas consequuntur sapiente commodi. Provident nihil consectetur rerum debitis illum omnis sed.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(17, 6, 6, 'Reiciendis et tempore recusandae. Consequatur commodi ducimus quos et repellat aspernatur laborum.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(18, 6, 6, 'Iste error accusantium porro qui dolorem. Quam et sequi adipisci eveniet optio beatae suscipit.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(19, 3, 7, 'Dolorem dolor tempora est voluptates eum. Commodi necessitatibus ut tenetur tempore id totam nihil. Sed repudiandae sit quaerat vitae debitis aperiam.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
(20, 2, 7, 'Voluptatem dolor aperiam nam. Sapiente hic eius laboriosam aperiam aut natus molestiae.', '2026-11-10 16:57:29', '2026-11-10 16:57:29'),
